#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────


# Run from anywhere: paths below are from the repo root. FROM=n starts at stage n on a re-run.
cd "$(git rev-parse --show-toplevel)"
ENV_FILE=apps/mobile/.env
APP_ID=app.gethopon
CF_WORKERS=https://dash.cloudflare.com/51a5a41f7bd8425703a6f1d92f867f4d/workers-and-pages
TOTAL_STAGES=11

# run_stage "Name" fn: shows the stage, then runs fn unless FROM skips past it.
run_stage() {
  stage "$1"
  if (( _STAGE_INDEX < ${FROM:-1} )); then note "skipped (FROM=${FROM})"; return; fi
  "$2"
}
# api_url makes sure the Worker URL is known, asking for it when an earlier stage was skipped.
api_url() {
  while [[ "${EXPO_PUBLIC_API_URL:-}" != https://* ]]; do
    ask EXPO_PUBLIC_API_URL "Paste the Worker URL (https://hopon.….workers.dev):"
  done
  EXPO_PUBLIC_API_URL=${EXPO_PUBLIC_API_URL%/}
}
# eas_app runs the EAS CLI from the app; a failure stops the wizard so you can re-run from that stage.
eas_app() {
  (cd apps/mobile && eas "$@") || {
    warn "eas $* failed. Fix it, then re-run with FROM=$_STAGE_INDEX scripts/store-setup.sh"
    exit 1
  }
}

artwork() {
  say "Three 1024×1024 PNGs go in apps/mobile/assets/ (app.json points at them):"
  step "icon.png: the iOS and store icon. Square, no transparency, no rounded corners."
  step "adaptive-icon.png: Android's foreground. Keep the art in the middle ~66%; Android crops the rest. Transparent background (#1C1D45 is filled in)."
  step "splash-icon.png: the logo on the launch screen, on transparent. Shown 200pt wide on #1C1D45."
  mkdir -p apps/mobile/assets
  local f info missing
  while :; do
    pause "Press Enter once the files are in place"
    missing=0
    for f in icon adaptive-icon splash-icon; do
      info=$(file -b "apps/mobile/assets/$f.png" 2>/dev/null || true)
      if [[ "$info" == "PNG image data, 1024 x 1024,"* ]]; then printf '  %s✓%s %s.png\n' "$GREEN" "$RESET" "$f"
      else warn "$f.png is missing or not a 1024×1024 PNG (${info:-no file})"; missing=1; fi
    done
    [[ "$(file -b apps/mobile/assets/icon.png 2>/dev/null)" == *RGBA* ]] &&
      warn "icon.png has an alpha channel: App Store Connect rejects that. Export it without transparency." && missing=1
    (( missing )) || break
  done
  note "Commit apps/mobile/assets/ with the other changes."
}

mailbox() {
  say "The Rules, Support and Privacy pages, the app and both store listings show support@gethopon.app."
  say "gethopon.app's mail already goes to Zoho; make sure that address actually receives."
  open_url "https://mailadmin.zoho.com"
  step "Admin Console → Users → pick your user → Mail Accounts → Email alias → add support@gethopon.app"
  step "(or create it as its own user or group, if you'd rather)."
  step "From another account, send a test email to support@gethopon.app and check it arrives."
  pause "Press Enter once a test email has arrived"
}

accounts() {
  say "You need two paid developer accounts and a free Expo account. Skip any you already have."
  open_url "https://developer.apple.com/account"
  step "Apple: sign in. The page should show Apple Developer Program membership; if not, Enroll (US\$99/year, can take a day or two)."
  pause "Press Enter once Apple membership is active"
  open_url "https://play.google.com/console/signup"
  step "Google Play: create a developer account (US\$25 once). Identity verification can take a few days."
  note "A new personal account must run a closed test with 12 testers for 14 days before production. Internal testing (this wizard) isn't held up by that."
  pause "Press Enter once the Play Console opens for you"
  open_url "https://expo.dev/signup"
  step "Expo: sign up, or skip if you have an account."
  pause "Press Enter when done"
}

eas_link() {
  say "Sign the EAS CLI in and link the app to an EAS project."
  command -v eas >/dev/null 2>&1 || { warn "eas isn't installed: npm install -g eas-cli, then re-run with FROM=$_STAGE_INDEX"; exit 1; }
  if (cd apps/mobile && eas whoami >/dev/null 2>&1); then note "already signed in as $(cd apps/mobile && eas whoami 2>/dev/null | head -n1)"
  else eas_app login; fi
  step "eas init: answer yes to create the project @<you>/hopon."
  eas_app init
  note "eas init wrote extra.eas.projectId and owner into apps/mobile/app.json: commit that."
}

build_env() {
  say "Release builds read the API URL and Clerk key from EAS, not from .env."
  open_url "$CF_WORKERS"
  step "Workers & Pages → hopon: copy its workers.dev URL (also printed by pnpm run deploy)."
  api_url
  local path code
  for path in /api/games /privacy; do
    code=$(curl -s -o /dev/null -w '%{http_code}' "$EXPO_PUBLIC_API_URL$path" || true)
    if [[ "$code" == 200 ]]; then printf '  %s✓%s %s%s\n' "$GREEN" "$RESET" "$EXPO_PUBLIC_API_URL" "$path"
    else warn "$EXPO_PUBLIC_API_URL$path returned ${code:-nothing}. /privacy needs a deploy of the branch that added it: pnpm run deploy"; fi
  done
  say "The Clerk key: Enter keeps the pk_test key from apps/mobile/.env. Once #32 gives you a pk_live key, re-run with FROM=$_STAGE_INDEX and paste it."
  while [[ "${EXPO_PUBLIC_CLERK_PUBLISHABLE_KEY:-}" != pk_* ]]; do
    ask EXPO_PUBLIC_CLERK_PUBLISHABLE_KEY "Clerk publishable key (pk_…):"
  done
  local name
  for name in EXPO_PUBLIC_API_URL EXPO_PUBLIC_CLERK_PUBLISHABLE_KEY; do
    eas_app env:set --name "$name" --value "${!name}" --environment preview --environment production \
      --visibility plaintext --non-interactive >/dev/null
    printf '  %s✓ set%s EAS env %s (preview, production)\n' "$GREEN" "$RESET" "$name"
  done
}

ios_build() {
  say "EAS builds the iOS app in the cloud (about 15–30 minutes)."
  step "Sign in with your Apple ID when asked, and let EAS register $APP_ID and create the certificate and profile (answer yes)."
  confirm "Start the production iOS build now?" || { warn "Not built. Re-run with FROM=$_STAGE_INDEX"; exit 1; }
  eas_app build --platform ios --profile production
}

testflight() {
  say "Upload the build to App Store Connect. EAS creates the app record there if it's missing."
  step "Sign in with your Apple ID again if asked. For the app name: App Store names are unique, so if 'hopon' is taken, try e.g. 'hopon: tiny games'."
  eas_app submit --platform ios --latest
  open_url "https://appstoreconnect.apple.com/apps"
  step "hopon → TestFlight. Apple processes the build for 10–30 minutes; it then appears under iOS Builds."
  step "Internal Testing → + → create a group (e.g. Team), add yourself and any testers from your App Store Connect users."
  step "Testers get an email; install TestFlight on the phone and open the invite."
  pause "Press Enter once the build installs from TestFlight"
}

app_store_listing() {
  say "App Store Connect → hopon. Needed before App Store review (not for internal TestFlight)."
  api_url
  open_url "https://appstoreconnect.apple.com/apps"
  step "App Privacy → Privacy Policy URL: $EXPO_PUBLIC_API_URL/privacy"
  step "App Privacy → Data Collection → Yes, we collect data. Tick these, each Linked to the user, Not used for tracking, purpose App Functionality:"
  note "    Contact Info → Email Address (Clerk sign-in)"
  note "    Identifiers → User ID (account ID and @handle)"
  note "    User Content → Other User Content (games, comments, reports)"
  note "    Usage Data → Product Interaction (saves, likes, blocks)"
  step "Publish the App Privacy answers."
  step "The 1.0 version page → Support URL: $EXPO_PUBLIC_API_URL/support"
  step "App Information → Age Rating → Edit. Answer what the app does. hopon is rated 13+ (#51):"
  note "    user-generated content and social features: yes (public games, comments, likes)."
  note "    Don't claim social features are off for under-13s: that would require the Declared Age Range API."
  note "    No gambling, ads, purchases, or unrestricted web access (games run sandboxed, with no network)."
  pause "Press Enter once App Privacy and Age Rating are saved"
}

android_build() {
  say "EAS builds the Android app bundle (.aab) in the cloud and creates the upload keystore."
  step "Answer yes to 'Generate a new Android Keystore?'. EAS keeps it; never lose it."
  confirm "Start the production Android build now?" || { warn "Not built. Re-run with FROM=$_STAGE_INDEX"; exit 1; }
  eas_app build --platform android --profile production
  note "The build page's Download button gives the .aab: you'll upload it next."
}

play_internal() {
  say "Google only accepts the first upload by hand, so this one goes through the Play Console."
  open_url "https://expo.dev"
  step "Projects → hopon → Builds → the latest Android build → Download (the .aab)."
  open_url "https://play.google.com/console"
  step "Create app → name hopon, App, Free; accept the declarations."
  step "Test and release → Testing → Internal testing → Testers: create an email list, add yourself and testers."
  step "Create new release → upload the .aab → release name 1.0.0 → Save → Review → Start rollout."
  step "Copy the 'Join on the web' link from Testers and open it on an Android phone."
  pause "Press Enter once the app installs from internal testing"
}

play_content() {
  say "Play Console → hopon → Policy → App content. Each section opens from that page."
  api_url
  open_url "https://play.google.com/console"
  step "Privacy policy: $EXPO_PUBLIC_API_URL/privacy"
  step "App access: some functionality is restricted. Instructions for reviewers:"
  note "    Me → Sign in with any email ending +clerk_test@example.com, code 424242 (Clerk's test mode)."
  note "    With a Clerk production instance (#32) that test code won't work: give a real test inbox instead."
  step "Ads: No ads."
  step "Content rating: start the questionnaire, category Games or Social as fits; users interact and share content: yes."
  step "Target audience: 13–15, 16–17 and 18+ (no under-13s)."
  step "Data safety → collected, not shared, encrypted in transit, users can request deletion:"
  note "    Personal info → Email address, User IDs: App functionality, Account management"
  note "    App activity → Other user-generated content, Other actions (saves, likes, blocks): App functionality"
  note "    Delete account URL: $EXPO_PUBLIC_API_URL/privacy#delete-account"
  pause "Press Enter once every App content section shows as complete"
}

banner "hopon store setup (#31)"
run_stage "Artwork: icon, adaptive icon, splash" artwork
run_stage "Support mailbox: support@gethopon.app" mailbox
run_stage "Developer accounts: Apple, Google Play, Expo" accounts
run_stage "EAS: sign in and link the project" eas_link
run_stage "Build environment: API URL and Clerk key" build_env
run_stage "iOS production build" ios_build
run_stage "TestFlight" testflight
run_stage "App Store Connect: privacy and age rating" app_store_listing
run_stage "Android production build" android_build
run_stage "Play Console: internal testing" play_internal
run_stage "Play Console: app content" play_content
finish
say "Commit apps/mobile/assets/ and app.json's EAS project ID. Next builds: cd apps/mobile && eas build --platform all --profile production"
